import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse(`{"title":"Paramètres de l'application","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/parametres-application.md","filePath":"src/guide/admin/parametres-application.md"}`),i={name:"guide/admin/parametres-application.md"};function n(o,e,l,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="parametres-de-l-application" tabindex="-1">Paramètres de l&#39;application <a class="header-anchor" href="#parametres-de-l-application" aria-label="Permalink to &quot;Paramètres de l&#39;application&quot;">​</a></h1><p><strong>Paramètres de l&#39;application</strong>, en haut du menu de gauche, regroupe tout ce qui personnalise votre instance d&#39;ERA : son identité visuelle, ce qui s&#39;imprime sur les reçus, et deux réglages qui changent réellement le comportement de l&#39;app pour les autres utilisateurs.</p><p>Ces réglages valent pour tout l&#39;établissement, pas pour votre compte. Pour vos préférences personnelles (thème, langue, sécurité), voir <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a>.</p><h2 id="identite" tabindex="-1">Identité <a class="header-anchor" href="#identite" aria-label="Permalink to &quot;Identité&quot;">​</a></h2><p>Le <strong>nom de l&#39;application</strong> remplace « ERA » partout dans l&#39;interface, dans les e-mails et sur les documents générés. C&#39;est ce qui permet à l&#39;établissement d&#39;afficher son propre nom plutôt que celui du logiciel.</p><h2 id="couleurs" tabindex="-1">Couleurs <a class="header-anchor" href="#couleurs" aria-label="Permalink to &quot;Couleurs&quot;">​</a></h2><p>Une <strong>couleur primaire</strong> et une <strong>couleur secondaire</strong>, appliquées à toute l&#39;interface. Le bouton <strong>Réinitialiser</strong> ramène aux valeurs par défaut d&#39;ERA si un essai ne convient pas — utile avant de chercher à corriger une teinte à la main.</p><h2 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h2><p>Deux logos distincts, et la différence compte :</p><ul><li>Le <strong>logo complet</strong> s&#39;affiche dans le menu déployé et sur la page d&#39;accueil. C&#39;est aussi celui qui apparaît sur les bulletins et les reçus de paiement des sites qui n&#39;ont pas de logo propre (voir <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>).</li><li>Le <strong>logo icône</strong> s&#39;affiche dans le menu réduit. Si vous ne le renseignez pas, le logo complet est utilisé à sa place — ce qui donne souvent un résultat illisible une fois réduit. Prévoyez une version carrée.</li></ul><h2 id="accroche-d-accueil" tabindex="-1">Accroche d&#39;accueil <a class="header-anchor" href="#accroche-d-accueil" aria-label="Permalink to &quot;Accroche d&#39;accueil&quot;">​</a></h2><p>L&#39;<strong>accroche</strong> et le <strong>sous-titre</strong> affichés sur la page d&#39;accueil publique, saisis séparément pour chaque langue. Laissez un champ vide pour conserver le texte par défaut dans cette langue.</p><h2 id="personnalisation-des-recus" tabindex="-1">Personnalisation des reçus <a class="header-anchor" href="#personnalisation-des-recus" aria-label="Permalink to &quot;Personnalisation des reçus&quot;">​</a></h2><p>Ces champs s&#39;impriment sur <strong>chaque reçu de paiement généré</strong>, en plus du logo (celui du site de l&#39;élève s&#39;il en a un, sinon le logo complet) : adresse, téléphone, e-mail, message de remerciement et note de bas de page. Ces champs sont communs à tous les sites.</p><p>C&#39;est ici qu&#39;on met les mentions que la famille doit retrouver sur son justificatif. Les reçus déjà générés ne sont pas réécrits : le changement s&#39;applique aux reçus produits ensuite.</p><h2 id="rattachement-libre-service-des-parents" tabindex="-1">Rattachement libre-service des parents <a class="header-anchor" href="#rattachement-libre-service-des-parents" aria-label="Permalink to &quot;Rattachement libre-service des parents&quot;">​</a></h2><p>Ce réglage décide si un parent peut <strong>rechercher un élève déjà inscrit et se rattacher lui-même</strong> à son dossier.</p><ul><li><strong>Activé</strong> : le parent effectue la démarche seul depuis son portail (voir <a href="/era-guide/guide/parent/enfants-et-documents.html">Mes enfants et leurs documents</a>).</li><li><strong>Désactivé</strong> : cette possibilité disparaît du portail parent. Le rattachement doit alors être fait par l&#39;administration, depuis le dossier de l&#39;élève (voir <a href="/era-guide/guide/admin/eleves-tuteurs.html">Élèves et tuteurs</a>).</li></ul><p>Vérifiez ce réglage avant de conclure qu&#39;un parent « ne trouve pas » la fonction : elle peut simplement être désactivée pour l&#39;établissement.</p><h2 id="notation" tabindex="-1">Notation <a class="header-anchor" href="#notation" aria-label="Permalink to &quot;Notation&quot;">​</a></h2><p>Ce réglage décide <strong>comment la moyenne d&#39;une matière combine les notes de différents types d&#39;évaluation</strong> (devoir, composition, interrogation…).</p><ul><li><strong>Désactivé</strong> (comportement par défaut) : chaque note pèse selon le poids de son type d&#39;évaluation, tel que défini dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</li><li><strong>Activé</strong> : chaque type d&#39;évaluation pèse autant, quel que soit le nombre de notes qu&#39;il contient. Trois interrogations ne pèsent alors pas plus lourd qu&#39;une composition unique.</li></ul><p>C&#39;est un choix pédagogique, pas un détail d&#39;affichage : il change les moyennes calculées, donc les bulletins. Arrêtez-le avant la première publication de bulletins de l&#39;année, et évitez d&#39;en changer en cours d&#39;année.</p>',23)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
